/**
 * The world, as one SVG path, for the tour map.
 *
 * Natural Earth 1:110m land (public domain), via the world-atlas TopoJSON,
 * projected equirectangular and simplified with Douglas-Peucker at 0.16 map
 * units. Antarctica is cropped the way every web world map crops it, and
 * islands under 1.2 square units are dropped: at the size this renders they
 * were single grey pixels.
 *
 * Coordinates are degrees, shifted so the path starts at 0,0:
 *   x = longitude + 180   (0..360)
 *   y = 84 - latitude     (0..144)
 *
 * Generated by scripts/make-world-path.py. Do not edit by hand.
 */

export const WORLD_VIEWBOX = '0 0 360 144';
export const WORLD_TOP_LAT = 84;

/** Map coordinates for a latitude and longitude, in the viewBox above. */
export function project(lat: number, lon: number): { x: number; y: number } {
  return { x: lon + 180, y: WORLD_TOP_LAT - lat };
}

